import { AVATAR_SQUARE_OFFSET_BY_SIZE, HALF } from '../constants';
import type { CornerProps, GetCornerOffsetStyles } from './types';

export const getCornerOffsetStyles = ({
    avatarSize,
    cornerSize,
    borderSize = 0,
    shape = 'circle',
    actualAvatarSize = 0,
}: {
    avatarSize: CornerProps['avatarSize'];
    cornerSize: CornerProps['cornerSize'];
    borderSize: CornerProps['borderSize'];
    shape: CornerProps['shape'];
    actualAvatarSize: number;
}): GetCornerOffsetStyles => {
    const sizeDiff = avatarSize - actualAvatarSize;
    switch (shape) {
        case 'square':
            const squareOffset = AVATAR_SQUARE_OFFSET_BY_SIZE[avatarSize] - sizeDiff * HALF;

            return {
                'bottom-right': { transform: 'translate(-50%,-50%)', top: squareOffset, left: squareOffset },
                'bottom-left': { transform: 'translate(50%,-50%)', top: squareOffset, right: squareOffset },
                'top-left': { transform: 'translate(50%, 50%)', bottom: squareOffset, right: squareOffset },
                'top-right': { transform: 'translate(-50%, 50%)', bottom: squareOffset, left: squareOffset },
            };

        case 'circle':
        default:
            const circleOffset = getCornerOffset({ avatarSize, cornerSize, borderSize, avatarSizeDiff: sizeDiff });

            return {
                'bottom-right': { bottom: circleOffset, right: circleOffset },
                'bottom-left': { bottom: circleOffset, left: circleOffset },
                'top-left': { top: circleOffset, left: circleOffset },
                'top-right': { top: circleOffset, right: circleOffset },
            };
    }
};

const DEFAULT_OFFSET = 0;

/**
 * @desc Calculates the offset for the Icon based on the Avatar size
 */
const getCornerOffset = ({
    avatarSize,
    cornerSize = 0,
    borderSize = 0,
    avatarSizeDiff = 0,
}: {
    avatarSize: CornerProps['avatarSize'];
    cornerSize: CornerProps['cornerSize'];
    borderSize: CornerProps['borderSize'];
    avatarSizeDiff: number;
}): number => {
    if (!cornerSize || !avatarSize) {
        return DEFAULT_OFFSET;
    }

    const radius = (avatarSize - avatarSizeDiff) * HALF;
    const indicatorCenter = radius * Math.cos((45 * Math.PI) / 180) + radius;
    const offset = avatarSize - avatarSizeDiff - indicatorCenter - cornerSize * HALF - borderSize * HALF;

    return Math.floor(offset);
};
