const getClearSrc = src => src.split('?')[0];
const isImage = src => /\.(jpg|jpeg|png|webp|avif|gif)$/.test(getClearSrc(src));
const isVideo = src => /\.(mp4|mov|avi|mkv|webm)$/.test(getClearSrc(src));
const isAudio = src => /\.(wav|mp3)$/.test(getClearSrc(src));
const isPdf = src => /\.(pdf)$/.test(getClearSrc(src));
export const getSourceType = source => {
  const {
    src,
    type
  } = source;
  if (type) {
    return type;
  }
  if (isImage(src)) {
    return 'image';
  }
  if (isVideo(src)) {
    return 'video';
  }
  if (isAudio(src)) {
    return 'audio';
  }
  if (isPdf(src)) {
    return 'pdf';
  }
  return 'unknown';
};
export const getImageDefaultAlt = selectedSourceIndex => "Lightbox image ".concat(selectedSourceIndex + 1);
export const isSourceLoadable = source => {
  const sourceType = getSourceType(source);
  if (sourceType === 'unknown') {
    return false;
  }
  return true;
};