import React from 'react';
import { SkeletonRound, SkeletonSquare } from '@fiverr-private/feedback';
import { AVATAR_SIZES } from '../constants';
import { getSquareBorderRadius } from '../utils';
import type { AvatarSkeletonProps } from './types';

const AvatarSkeleton = ({
  size = 'xs',
  shape = 'circle',
  dataTrackTag = 'avatar_skeleton',
  dataTrackValue,
}: AvatarSkeletonProps) =>
  shape === 'circle' ? (
    <SkeletonRound dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} size={AVATAR_SIZES[size]} />
  ) : (
    <SkeletonSquare height={AVATAR_SIZES[size]} width={AVATAR_SIZES[size]} borderRadius={getSquareBorderRadius(size)} />
  );

AvatarSkeleton.displayName = 'AvatarSkeleton';
export default AvatarSkeleton;
