import React from 'react';
import { DotIndicator, INDICATOR_SIZES_MAP } from '@fiverr-private/data_display';
import Corner from '../Corner';
import { useAvatarContext } from '../AvatarContext';
import { AVATAR_SIZES } from '../constants';
import type { AvatarOnlineIndicatorProps } from './types';
import { INDICATOR_SIZES } from './constants';

const AvatarOnlineIndicator = ({
  isOnline,
  position = 'bottom-right',
  dataTestId,
  dataTrackTag = 'avatar_online_indicator',
}: AvatarOnlineIndicatorProps) => {
  const { size: avatarSize, shape } = useAvatarContext();

  const indicatorSize = INDICATOR_SIZES[avatarSize];
  const indicatorSizeNumber = INDICATOR_SIZES_MAP[indicatorSize];
  const borderWidth = indicatorSizeNumber < 10 ? 'sm' : 'md';

  return (
    <Corner
      shape={shape}
      position={position}
      avatarSize={AVATAR_SIZES[avatarSize]}
      cornerSize={indicatorSizeNumber}
      borderSize={borderWidth === 'sm' ? 1 : 2}
      dataTestId={dataTestId}
      zIndex="2"
    >
      <DotIndicator
        dataTrackTag={dataTrackTag}
        dataTrackValue={isOnline ? 'online' : 'offline'}
        type={isOnline ? 'success' : 'neutral'}
        borderWidth={borderWidth}
        size={indicatorSize}
      />
    </Corner>
  );
};

AvatarOnlineIndicator.displayName = 'AvatarOnlineIndicator';
export default AvatarOnlineIndicator;
