import React, { useEffect, useRef, useState } from 'react';
import { translate } from '@fiverr-private/i18n-react';
import { Video } from '@fiverr-private/media';
import { Lightbox, LightboxContent, LightboxHeader, LightboxLabel, Overlay } from '@fiverr-private/overlay';
import { Center, Container } from '@fiverr-private/layout_components';
import { PlaySolidIcon } from '@fiverr-private/visuals';
import { IconButton } from '@fiverr-private/button';
import { Fade } from '@fiverr-private/transition';
import { useAvatarContext } from '../AvatarContext';
import useMedia from '../hooks/useMedia';
import type { AvatarVideoProps } from './types';

const AvatarVideo = ({ src, autoPlay = false, dataTrackTag = 'avatar_video', ...restProps }: AvatarVideoProps) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const { size, videoAutoPlay, setVideoAutoPlay } = useAvatarContext();
  const [isAvatarHovered, setIsAvatarHovered] = useState(false);
  const [openLightbox, setOpenListbox] = useState(false);
  const { showMedia, isMediaLoaded, onMediaError, onMediaLoad } = useMedia(src);

  useEffect(() => {
    setVideoAutoPlay(autoPlay);

    if (autoPlay) {
      videoRef.current?.play();
      setVideoAutoPlay(true);

      const timer = setTimeout(() => {
        videoRef.current?.pause();
        setVideoAutoPlay(false);
      }, 5000);

      return () => {
        clearTimeout(timer);
      };
    }
  }, [autoPlay, setVideoAutoPlay]);

  return showMedia ? (
    <Container
      width="100%"
      height="100%"
      position="absolute"
      tabIndex={0}
      onFocus={() => {
        setIsAvatarHovered(true);
      }}
      onMouseEnter={() => {
        setIsAvatarHovered(true);
      }}
      onMouseLeave={() => {
        setIsAvatarHovered(false);
      }}
    >
      <Fade
        easing={{ enter: 'easeIn', exit: 'easeOut' }}
        duration={{ enter: 'fast1', exit: 'moderate2' }}
        delay="fast1"
        in={videoAutoPlay}
      >
        <Container width="100%" height="100%" backgroundColor="grey_400">
          <Video
            ref={videoRef}
            muted={true}
            controls={false}
            objectFit="cover"
            width="100%"
            height="100%"
            backgroundColor={isMediaLoaded ? undefined : 'grey_700'}
            src={src}
            onError={onMediaError}
            onLoad={onMediaLoad}
            dataTrackTag={dataTrackTag}
            {...restProps}
          />
        </Container>
      </Fade>
      {isAvatarHovered && (
        <Fade delay="fast1" in={isAvatarHovered}>
          <Overlay position="absolute" lockBodyScroll={false}>
            <Center height="100%">
              <IconButton
                onBlur={() => {
                  setIsAvatarHovered(false);
                }}
                onClick={() => {
                  setOpenListbox(true);
                  setVideoAutoPlay(false);
                }}
                aria-label={translate<string>('avatar.avatarVideo.play')}
                variant="ghost"
                colorScheme="white"
                shape="circle"
                size={size === 'xl' || size === '2xl' ? 'sm' : 'md'}
              >
                <PlaySolidIcon color="white" />
              </IconButton>
            </Center>
          </Overlay>
        </Fade>
      )}
      {openLightbox && src && (
        <Lightbox
          onClose={() => {
            setOpenListbox(false);
            setIsAvatarHovered(false);
          }}
          sourceInitialIndex={0}
          sources={[
            {
              src,
              type: 'video',
            },
          ]}
        >
          <LightboxHeader />
          <LightboxContent />
          <LightboxLabel />
        </Lightbox>
      )}
    </Container>
  ) : null;
};

AvatarVideo.id = 'AvatarVideo';
AvatarVideo.displayName = 'AvatarVideo';

export default AvatarVideo;
