import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { useAvatarContext } from '../AvatarContext';
import { getCornerOffsetStyles } from './utils';
import type { CornerProps } from './types';

const Corner = ({
  className,
  style,
  position = 'bottom-right',
  shape = 'circle',
  avatarSize,
  cornerSize,
  borderSize,
  dataTestId,
  children,
  backgroundColor,
  borderRadius,
  display,
  padding,
  zIndex,
}: CornerProps) => {
  const { actualAvatarSize } = useAvatarContext();
  const cornerPositionMapping = getCornerOffsetStyles({
    actualAvatarSize,
    avatarSize,
    cornerSize,
    borderSize,
    shape,
  });

  const cornerPositionStyles = cornerPositionMapping[position];

  return (
    <Container
      padding={padding}
      display={display}
      borderRadius={borderRadius}
      backgroundColor={backgroundColor}
      position="absolute"
      data-testid={dataTestId}
      className={className}
      zIndex={zIndex}
      style={{ ...cornerPositionStyles, ...style }}
    >
      {children}
    </Container>
  );
};

Corner.displayName = 'Corner';

export default Corner;
